SELECT\n    \"TIEMPO FCHA TRANSAC\".\"DIM TIE DIA NK\" AS \"DIM TIE DIA NK\",\n    \"F CHEQUES GERENCIA\".\"DIM BLOQUEO SK\" AS \"DIM BLOQUEO SK\",\n    \"CHEQUE GERENCIA\".\"CODIGO AREA\" AS \"CODIGO AREA\",\n    \"CHEQUE GERENCIA\".\"DIM CHG CODIGO OFICINA NK\" AS \"DIM CHG CODIGO OFICINA NK\",\n    \"OFICINA\".\"DIM OFI OFICINA NK\" AS \"DIM OFI OFICINA NK\",\n    \"CHEQUE GERENCIA\".\"CONCEPTO GENERACION\" AS \"CONCEPTO GENERACION\",\n    \"CHEQUE GERENCIA\".\"PRIMER BENEFICIARIO\" AS \"PRIMER BENEFICIARIO\",\n    \"CHEQUE GERENCIA\".\"TIPO DOCUMENTO PRIMERO\" AS \"TIPO DOCUMENTO PRIMERO\",\n    \"CHEQUE GERENCIA\".\"IDENTIFICACION PRIMERO\" AS \"IDENTIFICACION PRIMERO\",\n    \"CHEQUE GERENCIA\".\"SEGUNDO BENEFICIARIO\" AS \"SEGUNDO BENEFICIARIO\",\n    \"CHEQUE GERENCIA\".\"TIPO DOCUMENTO SEGUNDO\" AS \"TIPO DOCUMENTO SEGUNDO\",\n    \"CHEQUE GERENCIA\".\"IDENTIFICACION SEGUNDO\" AS \"IDENTIFICACION SEGUNDO\",\n    \"CHEQUE GERENCIA\".\"TERCER BENEFICIARIO\" AS \"TERCER BENEFICIARIO\",\n    \"CHEQUE GERENCIA\".\"TIPO DOCUMENTO TERCERO\" AS \"TIPO DOCUMENTO TERCERO\",\n    \"CHEQUE GERENCIA\".\"IDENTIFICACION TERCERO\" AS \"IDENTIFICACION TERCERO\",\n    \"CHEQUE GERENCIA\".\"CONJUNCION\" AS \"CONJUNCION\",\n    \"CHEQUE GERENCIA\".\"FECHA EXPEDICION\" AS \"FECHA EXPEDICION\",\n    \"CHEQUE GERENCIA\".\"DIM CHG NUMERO CHEQUE GER NK\" AS \"DIM CHG NUMERO CHEQUE GER NK\",\n    \"CHEQUE GERENCIA\".\"VALOR\" AS \"VALOR\",\n    \"CHEQUE GERENCIA\".\"ESTADO CHEQUE\" AS \"ESTADO CHEQUE\",\n    CASE WHEN :filtro_nuevo = 'DM_CHQGEREN_009' THEN \"CHEQUE GERENCIA\".\"UBICACION CHEQUE\" ELSE NULL END AS \"UBICACION CHEQUE\",\n    CASE WHEN :filtro_nuevo = 'DM_CHQGEREN_009' THEN \"F CHEQUES GERENCIA\".\"COD USUARIO GENERA TRX\" ELSE NULL END AS \"COD USUARIO GENERA TRX\",\n    CASE WHEN :filtro_nuevo = 'DM_CHQGEREN_009' THEN \"F CHEQUES GERENCIA\".\"OBSERVACIONES\" ELSE NULL END AS \"OBSERVACIONES\",\n    CASE WHEN :filtro_nuevo = 'DM_CHQGEREN_009' THEN \"OFICINA\".\"NOMBRE REGION\" ELSE NULL END AS \"NOMBRE REGION\",\n    CASE WHEN :filtro_nuevo = 'DM_CHQGEREN_009' THEN \"OFICINA\".\"NOMBRE OFICINA\" ELSE NULL END AS \"NOMBRE OFICINA\",\n    CASE WHEN :filtro_nuevo = 'DM_CHQGEREN_009' THEN \"OFICINA\".\"DIM OFI REGION NK\" ELSE NULL END AS \"DIM OFI REGION NK\"\nFROM \n    \"CBS - CHEQUES_GERENCIA\".\"CHEQUE GERENCIA\" \"CHEQUE GERENCIA\"\n    JOIN \"CBS - CHEQUES_GERENCIA\".\"TIEMPO FCHA TRANSAC\" \"TIEMPO FCHA TRANSAC\" ON 1=1\n    JOIN \"CBS - CHEQUES_GERENCIA\".\"F CHEQUES GERENCIA\" \"F CHEQUES GERENCIA\" ON \"CHEQUE GERENCIA\".\"DIM CHEQUE GERENCIA SK\" = \"F CHEQUES GERENCIA\".\"DIM CHEQUE GERENCIA SK\"\n    LEFT JOIN \"CBS - CHEQUES_GERENCIA\".\"OFICINA\" \"OFICINA\" ON \"F CHEQUES GERENCIA\".\"DIM OFICINA SK\" = \"OFICINA\".\"DIM OFICINA SK\"\n    LEFT JOIN \"CBS - CHEQUES_GERENCIA\".\"ESTADO\" \"ESTADO\" ON \"F CHEQUES GERENCIA\".\"DIM ESTADO SK\" = \"ESTADO\".\"DIM ESTADO SK\"\nWHERE\n    (\n        (:filtro_nuevo = 'DM_CHQGEREN_006' AND\n         \"TIEMPO FCHA TRANSAC\".\"DIM TIE DIA NK\" = :P_FECHA AND\n         \"CHEQUE GERENCIA\".\"CODIGO AREA\" IN (:P_OFICINA) AND\n         \"CHEQUE GERENCIA\".\"CONCEPTO GENERACION\" IN (:P_CONCEPTO))\n        OR\n        (:filtro_nuevo = 'DM_CHQGEREN_009' AND\n         \"TIEMPO FCHA TRANSAC\".\"DIM TIE DIA NK\" >= :P_FECHA_DESDE AND\n         \"TIEMPO FCHA TRANSAC\".\"DIM TIE DIA NK\" <= :P_FECHA_HASTA AND\n         \"CHEQUE GERENCIA\".\"DIM CHG CODIGO_OFICINA NK\" IN (:P_OFICINA) AND\n         \"CHEQUE GERENCIA\".\"DIM CHG NUMERO_CHEQUE_GER NK\" LIKE :P_CHEQUE AND\n         \"CHEQUE GERENCIA\".\"VALOR\" LIKE :P_VALOR AND\n         \"F CHEQUES GERENCIA\".\"DIM TIE FECHA TRANSAC SK\" = \"TIEMPO FCHA TRANSAC\".\"DIM TIEMPO SK\")\n    )\nORDER BY\n    \"CHEQUE GERENCIA\".\"DIM CHG CODIGO_OFICINA NK\" ASC,\n    \"OFICINA\".\"DIM OFI OFICINA NK\" ASC,\n    \"CHEQUE GERENCIA\".\"DIM CHG NUMERO_CHEQUE_GER NK\" ASC